const fizzbuzz = (n) => {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push("FizzBuzz");
    else if (i % 3 === 0) out.push("Fizz");
    else if (i % 5 === 0) out.push("Buzz");
    else out.push(i);
  }
  return out;
};

console.log(fizzbuzz(15));
// [ 1, 2, 'Fizz', 4, 'Buzz', 'Fizz', 7, 8, 'Fizz', 'Buzz', 11, 'Fizz', 13, 14, 'FizzBuzz' ]

The order of the checks matters: test the combined case first, otherwise i % 3 matches 15 and you never reach "FizzBuzz". Checking i % 15 === 0 is equivalent to i % 3 === 0 && i % 5 === 0. Build a fresh result array and return it rather than logging inside the loop, so the function is reusable and testable.

