const firstDuplicate = (arr) => {
  const seen = new Set();
  for (const value of arr) {
    if (seen.has(value)) return value;
    seen.add(value);
  }
  return null;
};

console.log(firstDuplicate(["a", "b", "a", "c", "b"])); // a
console.log(firstDuplicate([1, 2, 3]));                     // null

Set.has is O(1), so the whole scan is O(n) instead of the O(n^2) you get from includes inside a loop. Returning inside for...of exits the function immediately — that is the early stop. A forEach callback cannot break, but return inside forEach only skips one iteration and keeps going, which is a common bug when people try to convert this code.

