const findInGrid = (grid, target) => {
  let found = null;
  outer: for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < grid[row].length; col++) {
      if (grid[row][col] === target) {
        found = [row, col];
        break outer;
      }
    }
  }
  return found;
};

A cleaner version returns directly and needs no label:

const findInGrid = (grid, target) => {
  for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < grid[row].length; col++) {
      if (grid[row][col] === target) return [row, col];
    }
  }
  return null;
};

console.log(findInGrid(grid, 5)); // [ 1, 1 ]
console.log(findInGrid(grid, 9)); // null

A return exits both loops and the function, which is simpler than a label plus variables. Labels are useful when you must break out and then continue work in the same function; then declare the result variable before the loop so it is still in scope after break.

